<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {api,message} from '../api'
import type {Department,Role} from '../types'
import Icon from './Icon.vue'
import Modal from './Modal.vue'
const props=defineProps<{roles:Role[];departments:Department[]}>();const emit=defineEmits<{updated:[]}>()
const roleOpen=ref(false);const departmentOpen=ref(false);const editing=ref(false);const busy=ref(false);const error=ref('');const departmentId=ref('')
const permissionOptions=ref<{code:string;name:string;globalOnly:boolean}[]>([])
const roleForm=ref({code:'',name:'',permissions:['spaces.read']});const depForm=ref({code:'',name:''})
const builtin=(code:string)=>['ADMIN','SPACE_MANAGER','AUDITOR','MEMBER'].includes(code)
onMounted(async()=>{try{permissionOptions.value=await api('/permissions')}catch(e){error.value=message(e)}})
function showRole(role?:Role){editing.value=!!role;roleForm.value=role?{code:role.code,name:role.name,permissions:[...role.permissions]}:{code:'',name:'',permissions:['spaces.read']};error.value='';roleOpen.value=true}
function showDepartment(dep?:Department){departmentId.value=dep?.id??'';depForm.value=dep?{code:dep.code,name:dep.name}:{code:'',name:''};error.value='';departmentOpen.value=true}
async function saveRole(){busy.value=true;error.value='';try{if(!roleForm.value.permissions.length)throw new Error('请至少选择一项权限');await api(editing.value?`/roles/${roleForm.value.code}`:'/roles',editing.value?'PUT':'POST',roleForm.value);roleOpen.value=false;emit('updated')}catch(e){error.value=message(e)}finally{busy.value=false}}
async function saveDepartment(){busy.value=true;error.value='';try{await api(departmentId.value?`/departments/${departmentId.value}`:'/departments',departmentId.value?'PUT':'POST',depForm.value);departmentOpen.value=false;emit('updated')}catch(e){error.value=message(e)}finally{busy.value=false}}
</script>
<template><section class="panel section-space"><div class="panel-heading"><div><h2>角色与授权</h2><p>内置角色保持稳定；自定义角色按成员所属院系限定数据范围。</p></div><button class="text-link" @click="showRole()"><Icon name="plus" :size="16"/>新增角色</button></div><div class="table-scroll"><table><thead><tr><th>角色</th><th>权限</th><th class="align-right">操作</th></tr></thead><tbody><tr v-for="role in props.roles" :key="role.code"><td><strong>{{role.name}}</strong><small class="subtext mono">{{role.code}}</small></td><td><div class="feature-chips"><span v-for="permission in role.permissions" :key="permission">{{permissionOptions.find(p=>p.code===permission)?.name??permission}}</span></div></td><td class="align-right"><span v-if="builtin(role.code)" class="muted">内置角色</span><button v-else class="text-link" @click="showRole(role)">编辑</button></td></tr></tbody></table></div></section><section class="panel section-space"><div class="panel-heading"><div><h2>院系目录</h2><p>用于成员归属和空间权限范围，编号创建后保持不变。</p></div><button class="text-link" @click="showDepartment()"><Icon name="plus" :size="16"/>新增院系</button></div><div class="table-scroll"><table><thead><tr><th>院系</th><th>编号</th><th class="align-right">操作</th></tr></thead><tbody><tr v-for="dep in props.departments" :key="dep.id"><td><strong>{{dep.name}}</strong></td><td class="mono">{{dep.code}}</td><td class="align-right"><button class="text-link" @click="showDepartment(dep)">编辑名称</button></td></tr></tbody></table></div></section><p v-if="error&&!roleOpen&&!departmentOpen" class="form-error" role="alert">{{error}}</p>
<Modal v-if="roleOpen" :title="editing?'编辑自定义角色':'新增自定义角色'" @close="roleOpen=false"><form class="form-body" @submit.prevent="saveRole"><label>角色编号<input v-model="roleForm.code" required pattern="[A-Z][A-Z0-9_]{2,31}" maxlength="32" :disabled="editing" placeholder="如 LIBRARIAN"><small>3–32 位大写字母、数字或下划线，以字母开头。</small></label><label>角色名称<input v-model="roleForm.name" required maxlength="64"></label><fieldset class="role-fieldset"><legend>授予权限</legend><label v-for="permission in permissionOptions.filter(p=>!p.globalOnly)" :key="permission.code" class="role-option"><input v-model="roleForm.permissions" type="checkbox" :value="permission.code"><div><strong>{{permission.name}}</strong><small>{{permission.code}}</small></div></label></fieldset><p class="muted small-text">账号与全平台通知管理仅授予内置系统管理员。</p><p v-if="error" class="form-error" role="alert">{{error}}</p><div class="form-actions"><button type="button" class="button secondary" @click="roleOpen=false">取消</button><button class="button" :disabled="busy">保存角色</button></div></form></Modal>
<Modal v-if="departmentOpen" :title="departmentId?'编辑院系':'新增院系'" @close="departmentOpen=false"><form class="form-body" @submit.prevent="saveDepartment"><label>院系编号<input v-model="depForm.code" pattern="[A-Z0-9_-]{2,32}" required :disabled="!!departmentId" maxlength="32" placeholder="如 EIE"></label><label>院系名称<input v-model="depForm.name" required maxlength="100"></label><p v-if="error" class="form-error" role="alert">{{error}}</p><div class="form-actions"><button type="button" class="button secondary" @click="departmentOpen=false">取消</button><button class="button" :disabled="busy">保存院系</button></div></form></Modal></template>
